<script setup lang="ts">
import { computed, ref } from 'vue'
import { useStudioStore } from '@/stores/studio'
import AppIcon from '@/components/AppIcon.vue'
const studio = useStudioStore()
const categories = ['全部', '角色', '地点', '规则', '章节摘要']
const category = ref('全部')
const query = ref('')
const selection = ref('')
const entries = computed(() => studio.project?.knowledge.filter(item => (category.value === '全部' || item.category === category.value) && `${item.title}${item.content}`.includes(query.value)) ?? [])
const entry = computed(() => entries.value.find(item => item.id === selection.value) ?? entries.value[0])
function add() { const id = studio.addKnowledge(category.value === '全部' ? '角色' : category.value); if (id) selection.value = id }
</script>
<template>
  <div v-if="studio.project" class="page knowledge-page"><div class="page-heading"><div><h1>设定与记忆</h1><p>让人物保持自己，让故事记得已经发生的事。</p></div><button class="button primary" :disabled="!studio.writable || category === '章节摘要'" @click="add"><AppIcon name="plus" :size="16" />添加条目</button></div><div class="knowledge-layout"><aside class="knowledge-index"><label class="search-field"><AppIcon name="search" :size="15" /><input v-model="query" placeholder="搜索设定" aria-label="搜索设定" /></label><div class="category-tabs" role="group" aria-label="设定分类"><button v-for="item in categories" :key="item" :class="{ active: category === item }" :aria-pressed="category === item" @click="category = item">{{ item }}</button></div><button v-for="item in entries" :key="item.id" class="knowledge-entry" :class="{ active: entry?.id === item.id }" @click="selection = item.id"><span class="entity-avatar"><AppIcon :name="item.category === '角色' ? 'user-round' : item.category === '地点' ? 'map-pin' : item.category === '章节摘要' ? 'history' : 'orbit'" :size="18" /></span><span><strong>{{ item.title }}</strong><small>{{ item.category }}<template v-if="item.tags.filter(t => !t.includes(':')).length"> · {{ item.tags.filter(t => !t.includes(':')).join('、') }}</template></small></span><AppIcon name="chevron-right" :size="14" /></button><div v-if="!entries.length" class="empty-state compact">还没有匹配的设定。<br>试试其他分类或关键词。</div></aside><article v-if="entry" class="knowledge-detail"><div class="entity-detail-head"><span class="entity-avatar large"><AppIcon :name="entry.category === '角色' ? 'user-round' : entry.category === '地点' ? 'map-pin' : 'notebook-pen'" :size="27" /></span><div><h2 v-if="!studio.writable || entry.category === '章节摘要'">{{ entry.title }}</h2><input v-else v-model="entry.title" class="entity-title-input" aria-label="条目名称" @input="studio.changed()" /><span class="entity-category">{{ entry.category === '章节摘要' ? '已确认的章节记忆' : entry.category }}</span></div><span class="status-label complete">{{ entry.category === '章节摘要' ? '定稿后整理' : '作者设定' }}</span></div><div class="entity-tags"><span v-for="tag in entry.tags.filter(t => !t.includes(':'))" :key="tag">{{ tag }}</span></div><label for="entity-content">{{ entry.category === '章节摘要' ? '本章确立的事实' : '关于这个设定' }}</label><textarea id="entity-content" v-model="entry.content" :readonly="!studio.writable || entry.category === '章节摘要'" rows="13" placeholder="写下你希望故事记住的内容。" @input="studio.changed()" /><div class="entity-usage"><AppIcon name="link-2" :size="18" /><div><strong>作为后续创作的参考</strong><p>{{ entry.category === '章节摘要' ? '仅在来源章节早于当前章节、且来源正文版本仍匹配时，注入后续章节。正文修改后，旧摘要不再自动引用。' : '条目会在上下文预算内提供给 AI。你可以在伴写面板中预览实际发送的内容。' }}</p></div></div></article><div v-else class="knowledge-detail empty-state"><AppIcon name="notebook-tabs" :size="32" /><h2>给故事一个记忆的地方</h2><p>人物、地点与规则，都会成为后续写作的参考。</p></div></div></div>
</template>
